class Distribution:
    """A scalar value or array values with associated uncertainty distribution.

    This object will take its exact type from whatever the ``samples``
    argument is. In general this is expected to be ``NdarrayDistribution`` for
    |ndarray| input, and, e.g., ``QuantityDistribution`` for a subclass such
    as |Quantity|. But anything compatible with `numpy.asanyarray` is possible
    (generally producing ``NdarrayDistribution``).

    See also: https://docs.astropy.org/en/stable/uncertainty/

    Parameters
    ----------
    samples : array-like
        The distribution, with sampling along the *trailing* axis. If 1D, the sole
        dimension is used as the sampling axis (i.e., it is a scalar distribution).
        If an |ndarray| or subclass, the data will not be copied unless it is not
        possible to take a view (generally, only when the strides of the last axis
        are negative).

    """

    _generated_subclasses = {}

    @staticmethod
    def _get_distribution_dtype(dtype, n_samples, itemsize=None):
        """Make the structured dtype used to hide the sample dimension."""
        dtype = np.dtype(dtype)
        if itemsize is None:
            itemsize = dtype.itemsize
        if itemsize < dtype.itemsize:
            raise ValueError("new type is not compatible with the sample layout")
        sample_dtype = np.dtype(
            {"names": ["sample"], "formats": [dtype], "itemsize": itemsize}
        )
        return np.dtype([("samples", sample_dtype, (operator.index(n_samples),))])

    def __new__(cls, samples):
        if isinstance(samples, Distribution):
            samples = samples.distribution
        samples = np.asanyarray(samples)
        if samples.shape == ():
            raise TypeError("Attempted to initialize a Distribution with a scalar")

        n_samples = samples.shape[-1]
        samples_cls = samples.__class__
        if cls is Distribution:
            distr_cls = cls._generated_subclasses.get(samples_cls)
            if distr_cls is None:
                name = f"{samples_cls.__name__.capitalize()}Distribution"
                distr_cls = type(
                    name,
                    (_DistributionRepr, ArrayDistribution, samples_cls),
                    {"_samples_cls": samples_cls, "__module__": cls.__module__},
                )
                cls._generated_subclasses[samples_cls] = distr_cls
        else:
            distr_cls = cls

        stride = samples.strides[-1]
        # A record dtype can describe positive spacing between samples.  A
        # negative stride cannot be represented by a dtype and needs a copy.
        if stride < samples.dtype.itemsize or (stride == 0 and n_samples != 1):
            samples = samples.copy()
            stride = samples.strides[-1]
        if stride == 0:  # the sole sample of a broadcast array
            stride = samples.dtype.itemsize

        dtype = cls._get_distribution_dtype(samples.dtype, n_samples, stride)
        interface = samples.__array_interface__.copy()
        interface.update(
            shape=samples.shape[:-1],
            strides=samples.strides[:-1] or None,
            typestr=dtype.str,
            descr=dtype.descr,
        )
        raw = np.asarray(DummyArray(interface, base=samples))
        if samples_cls is not np.ndarray:
            raw = raw.view(samples_cls)
            # Calling Quantity.__array_finalize__ here would try to reshape a
            # structured unit to match our private wrapper dtype.  The public
            # sample dtype is unchanged, so copy the subclass metadata
            # directly and let the final Distribution view finalize normally.
            if hasattr(samples, "__dict__"):
                raw.__dict__.update(samples.__dict__)
        return raw.view(distr_cls)

    @property
    def n_samples(self):
        return super().dtype["samples"].shape[-1]

    def __array_function__(self, function, types, args, kwargs):
        if function in UNSUPPORTED_FUNCTIONS:
            return self._not_implemented_or_raise(function, types)
        if function in DISPATCHED_FUNCTIONS:
            try:
                return DISPATCHED_FUNCTIONS[function](*args, **kwargs)
            except NotImplementedError:
                return self._not_implemented_or_raise(function, types)
        if function in FUNCTION_HELPERS:
            try:
                args, kwargs, out = FUNCTION_HELPERS[function](*args, **kwargs)
            except NotImplementedError:
                return self._not_implemented_or_raise(function, types)
            result = function(*args, **kwargs)
            if out is not None:
                return out
            return self._wrap_result(result)
        if function in DISTRIBUTION_SAFE_FUNCTIONS:
            return super().__array_function__(function, types, args, kwargs)
        return super().__array_function__(function, types, args, kwargs)

    @classmethod
    def _wrap_result(cls, result, sample_axis=-1):
        if isinstance(result, tuple):
            return tuple(cls._wrap_result(x, sample_axis) for x in result)
        if isinstance(result, list):
            return [cls._wrap_result(x, sample_axis) for x in result]
        if isinstance(result, Distribution):
            return result
        if not isinstance(result, np.ndarray) or result.shape == ():
            return result
        if sample_axis != -1:
            result = np.moveaxis(result, sample_axis, -1)
        return Distribution(result)

    def __array_ufunc__(self, function, method, *inputs, **kwargs):
        if kwargs.get("axes") is not None:
            raise NotImplementedError(
                "the 'axes' keyword is not supported for Distribution gufuncs"
            )

        distributions = [x for x in inputs if isinstance(x, Distribution)]
        if not distributions:
            return NotImplemented
        n_samples = distributions[0].n_samples
        if any(x.n_samples != n_samples for x in distributions[1:]):
            raise ValueError("all Distribution arguments must have equal n_samples")

        if method == "outer":
            if len(inputs) != 2:
                return NotImplemented
            left, right = inputs
            left_ndim = np.ndim(left)
            right_ndim = np.ndim(right)
            left = (
                left.distribution
                if isinstance(left, Distribution)
                else np.asanyarray(left)[..., np.newaxis]
            )
            right = (
                right.distribution
                if isinstance(right, Distribution)
                else np.asanyarray(right)[..., np.newaxis]
            )
            left = left.reshape(left.shape[:-1] + (1,) * right_ndim + (n_samples,))
            right = right.reshape((1,) * left_ndim + right.shape)
            out = kwargs.pop("out", None)
            if out is not None:
                out = out if isinstance(out, tuple) else (out,)
                if not isinstance(out[0], Distribution):
                    raise TypeError("ufunc outer output must be a Distribution")
                kwargs["out"] = (out[0].distribution,)
            result = function(left, right, **kwargs)
            return out[0] if out is not None else Distribution(result)

        if method == "at":
            target = inputs[0]
            if not isinstance(target, Distribution):
                return NotImplemented
            converted = [target.distribution, inputs[1]]
            for value in inputs[2:]:
                if isinstance(value, Distribution):
                    converted.append(value.distribution)
                else:
                    value = np.asanyarray(value)
                    converted.append(
                        value if value.ndim == 0 else value[..., np.newaxis]
                    )
            return function.at(*converted, **kwargs)

        signature = function.signature
        output_sample_axes = None
        if signature and method == "__call__":
            input_core, output_core = _parse_gufunc_signature(signature.replace("?", ""))
            converted = []
            for value, core in zip(inputs, input_core):
                core_ndim = len(core)
                if isinstance(value, Distribution):
                    array = value.distribution
                    converted.append(np.moveaxis(array, -1, -core_ndim - 1))
                else:
                    array = np.asanyarray(value)
                    if array.ndim == 0:
                        converted.append(array)
                        continue
                    array = np.expand_dims(array, array.ndim - core_ndim)
                    converted.append(array)
            inputs = tuple(converted)
            output_sample_axes = tuple(-len(core) - 1 for core in output_core)
