function_helper = FunctionAssigner(FUNCTION_HELPERS)
dispatched_function = FunctionAssigner(DISPATCHED_FUNCTIONS)


def _is_distribution(value):
    # Local import avoids a cycle while core imports this registry.
    from .core import Distribution

    return isinstance(value, Distribution)


def _convert_out(kwargs):
    out = kwargs.get("out")
    if out is None:
        return None
    values = out if isinstance(out, tuple) else (out,)
    converted = []
    for value in values:
        if value is None:
            converted.append(None)
        elif _is_distribution(value):
            converted.append(value.distribution)
        else:
            raise NotImplementedError
    kwargs["out"] = tuple(converted) if isinstance(out, tuple) else converted[0]
    return out


@function_helper(
    helps={
        np.all,
        np.any,
        np.max,
        np.min,
        np.amax,
        np.amin,
        np.sum,
        np.prod,
        np.mean,
        np.std,
        np.var,
        np.median,
        np.ptp,
    }
)
def reduction_helper(a, axis=None, *args, **kwargs):
    if not _is_distribution(a):
        raise NotImplementedError
    if axis is None:
        axis = tuple(range(a.ndim))
    else:
        axes = (axis,) if np.isscalar(axis) else tuple(axis)
        axis = tuple(normalize_axis_index(x, a.ndim) for x in axes)
        if np.isscalar(axes[0]) and len(axes) == 1:
            axis = axis[0]
    out = _convert_out(kwargs)
    return (a.distribution, axis) + args, kwargs, out


@function_helper(helps={np.copy})
def copy_helper(a, *args, **kwargs):
    if not _is_distribution(a):
        raise NotImplementedError
    return (a.distribution,) + args, kwargs, None


@function_helper(helps={np.reshape})
def reshape_helper(a, newshape, *args, **kwargs):
    if not _is_distribution(a):
        raise NotImplementedError
    if np.isscalar(newshape):
        newshape = (newshape,)
    return (a.distribution, tuple(newshape) + (a.n_samples,)) + args, kwargs, None


@function_helper(helps={np.transpose})
def transpose_helper(a, axes=None):
    if not _is_distribution(a):
        raise NotImplementedError
    axes = tuple(reversed(range(a.ndim))) if axes is None else tuple(axes)
    axes = tuple(normalize_axis_index(x, a.ndim) for x in axes)
    return (a.distribution, axes + (a.ndim,)), {}, None


@function_helper(helps={np.swapaxes})
def swapaxes_helper(a, axis1, axis2):
    if not _is_distribution(a):
        raise NotImplementedError
    axis1 = normalize_axis_index(axis1, a.ndim)
    axis2 = normalize_axis_index(axis2, a.ndim)
    return (a.distribution, axis1, axis2), {}, None


@function_helper(helps={np.moveaxis})
def moveaxis_helper(a, source, destination):
    if not _is_distribution(a):
        raise NotImplementedError
    source = normalize_axis_tuple(source, a.ndim)
    destination = normalize_axis_tuple(destination, a.ndim)
    return (a.distribution, source, destination), {}, None


@function_helper(helps={np.squeeze})
def squeeze_helper(a, axis=None):
    if not _is_distribution(a):
        raise NotImplementedError
    if axis is not None:
        axis = normalize_axis_tuple(axis, a.ndim)
    return (a.distribution, axis), {}, None


@function_helper(helps={np.expand_dims})
def expand_dims_helper(a, axis):
    if not _is_distribution(a):
        raise NotImplementedError
    # normalize against the logical result dimensionality.
    axis = normalize_axis_tuple(axis, a.ndim + 1)
    return (a.distribution, axis), {}, None


@function_helper(helps={np.broadcast_to})
def broadcast_to_helper(array, shape, subok=False):
    if not _is_distribution(array):
        raise NotImplementedError
    return (array.distribution, tuple(shape) + (array.n_samples,)), {"subok": subok}, None


@dispatched_function(helps={np.empty_like})
def empty_like(a, dtype=None, order="K", subok=True, shape=None, *, device=None):
    from .core import Distribution

    if not _is_distribution(a):
        raise NotImplementedError
    sample_shape = a.distribution.shape if shape is None else tuple(shape) + (a.n_samples,)
    kwargs = {"dtype": dtype, "order": order, "subok": subok, "shape": sample_shape}
    if device is not None:
        kwargs["device"] = device
    return Distribution(np.empty_like(a.distribution, **kwargs))


@dispatched_function(helps={np.broadcast_arrays})
def broadcast_arrays(*args, subok=False):
    from .core import Distribution

    distributions = [arg for arg in args if _is_distribution(arg)]
    if not distributions:
        raise NotImplementedError
    n_samples = distributions[0].n_samples
    if any(arg.n_samples != n_samples for arg in distributions[1:]):
        raise ValueError("all Distribution arguments must have equal n_samples")
    shape = np.broadcast_shapes(*(arg.shape for arg in args))
    result = []
    for arg in args:
        if _is_distribution(arg):
            samples = np.broadcast_to(
                arg.distribution, shape + (n_samples,), subok=subok
            )
            result.append(Distribution(samples))
        else:
            result.append(np.broadcast_to(arg, shape, subok=subok))
    return result


@dispatched_function(helps={np.concatenate})
def concatenate(arrays, axis=0, out=None, *, dtype=None, casting="same_kind"):
    from .core import Distribution

    distributions = [arg for arg in arrays if _is_distribution(arg)]
    if not distributions:
        raise NotImplementedError
    n_samples = distributions[0].n_samples
    if any(arg.n_samples != n_samples for arg in distributions[1:]):
        raise ValueError("all Distribution arguments must have equal n_samples")
    converted = []
    for arg in arrays:
        if _is_distribution(arg):
            sample = arg.distribution
        else:
            ordinary = np.asanyarray(arg)
            sample = np.broadcast_to(
                ordinary[..., np.newaxis], ordinary.shape + (n_samples,), subok=True
            )
        converted.append(sample.reshape(-1, n_samples) if axis is None else sample)
    if axis is None:
        axis = 0
    else:
        axis = normalize_axis_index(axis, distributions[0].ndim)
    if out is not None:
        if not _is_distribution(out):
            raise TypeError("concatenate output must be a Distribution")
        output = out.distribution
    else:
        output = None
    kwargs = {"axis": axis, "out": output, "casting": casting}
    if dtype is not None:
        kwargs["dtype"] = dtype
    result = np.concatenate(converted, **kwargs)
    return out if out is not None else Distribution(result)


def _plain_storage(value):
    return value.distribution if _is_distribution(value) else value


@dispatched_function(helps={np.may_share_memory})
def may_share_memory(a, b, *args, **kwargs):
    return np.may_share_memory(
        _plain_storage(a), _plain_storage(b), *args, **kwargs
    )


@dispatched_function(helps={np.shares_memory})
def shares_memory(a, b, *args, **kwargs):
    return np.shares_memory(_plain_storage(a), _plain_storage(b), *args, **kwargs)

